// CSS (theme + prototype-specific) is loaded via the <link
// rel="stylesheet" href="/src/style.scss"> that generateProject injects
// into index.html's <head> — not a JS import here. A <link> is
// render-blocking like any normal stylesheet; a JS-imported CSS module is
// only injected once this script has executed (after first paint in dev),
// which is exactly what caused a brief flash of unstyled/default-browser
// text on load. See src/style.scss for how the theme CSS itself is pulled
// in (Sass @use on a plain .css file) alongside the prototype's own SCSS.

// Import Lyne elements index - this registers all Web Components
import '@sbb-esta/lyne-elements';

console.log('Prototype loaded - all Lyne components available');

// Dev-only page audit: in the browser run `await __lyneAudit({ responsive: true })`.
// It reports console errors, icons that didn't render, unregistered elements,
// broken trigger ids, horizontal overflow at phone/tablet/desktop width, ...
// (The guard keeps it out of the production build.)
if (import.meta.env.DEV) {
  import('./audit');
}

// Prototype behaviour
const root = document.documentElement;
const applyTheme = (dark: boolean) => {
  root.classList.toggle('sbb-dark', dark);
  root.classList.toggle('sbb-light', !dark);
  try {
    localStorage.setItem('theme', dark ? 'dark' : 'light');
  } catch {}
};
const param = new URLSearchParams(location.search);
const stored = (() => {
  try {
    return localStorage.getItem('theme');
  } catch {
    return null;
  }
})();
applyTheme((param.get('theme') ?? stored) === 'dark');
document.getElementById('theme-toggle')?.addEventListener('click', () => applyTheme(!root.classList.contains('sbb-dark')));

const tabGroup = document.getElementById('dashboard-tabs') as (HTMLElement & { tabs?: { labels?: unknown } }) | null;
const initialTab = param.get('tab');
document.getElementById('sidebar-home')?.addEventListener('click', () => {
  const labels = tabGroup?.querySelectorAll<HTMLElement>('sbb-tab-label');
  labels?.[0]?.click();
});
if (initialTab) {
  customElements.whenDefined('sbb-tab-group').then(() =>
    requestAnimationFrame(() => tabGroup?.querySelectorAll<HTMLElement>('sbb-tab-label')[Number(initialTab)]?.click()),
  );
}

const taskMenu = document.getElementById('task-menu') as (HTMLElement & { trigger: HTMLElement }) | null;
document.querySelectorAll<HTMLElement>('.app-task-menu').forEach((btn) => {
  btn.addEventListener('click', () => {
    if (!taskMenu || taskMenu.trigger === btn) return;
    taskMenu.trigger = btn;
    (taskMenu as HTMLElement & { open: () => void }).open();
  });
});

const filter = document.getElementById('task-filter');
filter?.addEventListener('change', () => {
  const value = (filter as HTMLElement & { value: string }).value;
  document.querySelectorAll<HTMLElement>('.app-task').forEach((row) => {
    row.hidden = value !== 'all' && row.dataset.state !== value;
  });
});
